  );
});

test("sorts ids inside a wave", () => {
  assert.deepEqual(buildPlan([{ id: "zed" }, { id: "alpha" }, { id: "mike" }]), {
    waves: [["alpha", "mike", "zed"]],
    order: ["alpha", "mike", "zed"],
  });
});

test("rejects duplicate ids", () => {
  assert.throws(
